INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Twenty One', '《灵魂筹码:契约》是一款生存恐怖对战游戏。这是一场一旦坐上牌桌便无法回头的赌局，为了取胜所要付出的代价远超想象，你需要通过合作才能逃离这越陷越深的泥潭。不过要小心，你将面对的敌人并不只有恶灵，而你要合作的也不仅仅是人类同伴……' FROM games WHERE igdb_id = 210894 ON CONFLICT (game_id, language_code) DO NOTHING;
