INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tengoku Struggle: Strayside', 'Rin Enma adopted daughter of King Enma–he who judges over the newly departed and ruler of the underworld–, is tasked to recapture “jailbreakers”, those who were punished to be in hell but have now escaped hell to the living world. Enlisting the help of Goemon and the others, she comes to the human world in hopes of recapturing the jailbreaks but the guys who are helping her to succeed in her mission are also punished, souls?! Not to mention a mysterious singer-songwriter wants to join in the fun?! Is he an enemy or an ally?' FROM games WHERE igdb_id = 195522 ON CONFLICT (game_id, language_code) DO NOTHING;
