INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bibi & Tina: New Adventures with Horses', 'A violent storm has hit the area near Martinshof. Mount up and see what damage the storm has done. Ride across the fields, jump over numerous obstacles and have Bibi the witch magic away the mess. But most of all, you can have lots of fun in fast-paced horse races, show off your jumping and slalom riding skills, take loving care of the horses and send photos to your worried friend Naomi in Australia.' FROM games WHERE igdb_id = 194979 ON CONFLICT (game_id, language_code) DO NOTHING;
