INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fault: Stp - Lightkravte', 'Fault: Stp - Lightkravte is the latest entry in the fault series, which has shipped over 500,000 copies worldwide. Lightkravte presents its story through the eyes of Khaji Oberg, an ordinary and unremarkable teenaged boy who finds himself reaching for a dream that slips ever further away from him.' FROM games WHERE igdb_id = 202479 ON CONFLICT (game_id, language_code) DO NOTHING;
